const root = $input.first().json;
if (!root || root.ok === false) throw new Error('AURELIUS API returned an error');
const campaigns = Array.isArray(root.campaigns) ? root.campaigns : [];
const tasks = Array.isArray(root.tasks) ? root.tasks : [];
const cap = root.capacity || {};
const date = new Date().toISOString().slice(0,10);
const verified = tasks.filter(t => t.status === 'verified' || t.status === 'sent').length;
const failed = tasks.filter(t => t.status === 'failed').length;
const active = campaigns.filter(c => c.status === 'approved').length;
const lines = [
  'AURELIUS — ежедневный отчёт ' + date,
  'Кампаний: ' + campaigns.length + ', активных: ' + active,
  'Плановая цель: ' + (cap.target || 0) + '/день',
  'Заданий в выдаче API: ' + tasks.length,
  'Отправлено/подтверждено: ' + verified,
  'Ошибок: ' + failed,
  '',
  'Внимание: отправлено Telegram-ботом ≠ подтверждено на внешней площадке.',
  'Не запускайте публикации без согласия администратора.'
];
return [{json:{text:lines.join('\\n')}}];
